<?php
require_once __DIR__.'/lib.php';require_login();$id=(int)($_POST['batch_id']??$_GET['id']??0);$action=$_POST['action']??'';$lock=null;
if(str_starts_with($action,'guided_')||isset($_GET['guided_stock'])||isset($_GET['guided_template'])){require __DIR__.'/guided_count_endpoint.php';exit;}
if(adjustments_ready()&&(($id&&final_count_is($id))||str_starts_with($action,'final_')||(!$id&&in_array($action,['create','manual_create'],true)))){require __DIR__.'/final_count_endpoint.php';exit;}
if(!adjustments_ready()||($id&&!adjustment_is_new($id))){require __DIR__.'/inventory_count_legacy_endpoint.php';exit;}
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();adjustment_access();$lock=inventory_write_lock();
 if($action==='manual_create'){$id=manual_adjustment_create($_POST);flash('Manual count snapshot created. Enter First Count and Recount before approval. No stock changed.');}
 elseif($action==='manual_save'){$errors=manual_adjustment_save($id,$_POST);flash($errors?'Manual count has errors. Review the validation list.':'Manual counts validated. No stock changed.',$errors?'danger':'success');}
 elseif($action==='create'){$id=adjustment_create($_POST);flash('Count snapshot created. No stock changed.');}
 elseif($action==='upload'){$file=$_FILES['file']??[];validate_upload_file($file,['xlsx']);$hash=hash_file('sha256',$file['tmp_name']);$rows=XlsxReader::rows($file['tmp_name']);$stored=store_upload($file,'count_evidence','COUNT');$errors=adjustment_upload($id,$rows,$file['name'],$hash,$stored);flash($errors?'Upload has errors. See the persistent error list.':'Counts saved. No stock changed.',$errors?'danger':'success');}
 elseif($action==='review'){adjustment_review($id,$_POST['reason']??'',$_POST['support_reference']??'',$_POST['revision']??0,!empty($_POST['review_ack']));flash('Reviewed. A different Admin must approve.');}
 elseif($action==='return_review'){adjustment_release_review($id,$_POST['reason']??'');flash('Returned for review. Approval invalidated.');}
 elseif($action==='post'){adjustment_post($id,$_POST['digest']??'',!empty($_POST['review_ack']));flash('Adjustment and redistribution posted once. Use the approved final allocations to update actual marketplaces.');}
 elseif($action==='cancel'){$reason=process_reason($_POST['reason']??'');process_transaction(function()use($id,$reason){count_cancel_pending($id);adjustment_event($id,'Cancelled',['reason'=>$reason]);});flash('Count cancelled. No stock changed.');}
 else throw new Exception('Invalid adjustment action.');inventory_write_unlock($lock);$lock=null;header('Location: index.php?page=inventory_count&id='.$id);exit;}
 $b=count_batch($id);$stage=($_GET['stage']??'First')==='Recount'?'Recount':'First';
 if(isset($_GET['evidence'])){$q=db()->prepare('SELECT * FROM count_upload_evidence WHERE id=? AND batch_id=?');$q->execute([(int)$_GET['evidence'],$id]);$v=$q->fetch();$base=realpath(__DIR__.'/uploads/count_evidence');$path=$v?realpath(__DIR__.'/'.$v['stored_path']):false;if(!$path||!$base||!str_starts_with(str_replace('\\','/',$path),str_replace('\\','/',$base).'/')||!hash_equals($v['file_hash'],hash_file('sha256',$path)))throw new Exception('Uploaded evidence is unavailable or changed.');header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="count_evidence_'.$v['id'].'.xlsx"');header('Cache-Control: private, no-store');readfile($path);exit;}
 if(isset($_GET['results'])){$r=inventory_report_build(['report'=>'adjustments','from'=>$b['count_date'],'to'=>$b['count_date']]);$r['rows']=array_values(array_filter($r['rows'],fn($row)=>$row[0]===$b['batch_ref']));$r['title']='Adjustment Record · '.$b['batch_ref'];if(($_GET['format']??'')==='print'){report_print_document($r['title'],$r['headers'],$r['rows'],report_meta($r));exit;}$path=tempnam(sys_get_temp_dir(),'adj-result-');try{report_write_xlsx($path,$r['title'],$r['headers'],$r['rows'],report_meta($r));header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$b['batch_ref'].'_Results.xlsx"');readfile($path);}finally{if(is_file($path))unlink($path);}exit;}
 if(isset($_GET['download'])){$path=tempnam(sys_get_temp_dir(),'adj-count-');try{adjustment_export($id,$path,$stage);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$b['batch_ref'].'_'.$stage.'_R'.$b['revision'].'.xlsx"');readfile($path);}finally{if(is_file($path))unlink($path);}exit;}
 if(isset($_GET['print'])){$rows=[];foreach(count_lines($id) as $l)$rows[]=[$l['master_sku'],$l['product_name'],(int)$l['on_hand'],'','','','',''];report_print_document('Physical Inventory Count Sheet',['Master SKU','Product Description','On Hand','Actual Good','Actual Packaging','Actual Damaged','Actual Other Restricted','Remarks'],$rows,['Batch'=>$b['batch_ref'],'Revision'=>$b['revision'],'Stage'=>$stage,'Cutoff'=>$b['cutoff_at'],'Counted By'=>'________________','Instructions'=>'Zero means counted zero. Leave uncounted rows blank.']);exit;}
 header('Location: index.php?page=inventory_count&id='.$id);exit;
}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();if($_SERVER['REQUEST_METHOD']==='POST'&&$lock&&$id&&can_action('upload_inventory_count'))try{adjustment_event($id,'Rejected action',['action'=>$action,'error'=>safe_error_message($ex)]);}catch(Throwable $ignored){}inventory_write_unlock($lock);flash(safe_error_message($ex),'danger');header('Location: index.php?page=inventory_count'.($id?'&id='.$id:''));exit;}
